function coordinateEqual(a,b){return Array.isArray(a)&&Array.isArray(b)&&Number(a[0])===Number(b[0])&&Number(a[1])===Number(b[1])}
function editableSequences(geometry){const sequences=[];const add=(coordinates,closed=false)=>{if(Array.isArray(coordinates)&&coordinates.length)sequences.push({coordinates,closed})};if(geometry?.type==='LineString')add(geometry.coordinates);else if(geometry?.type==='MultiLineString')geometry.coordinates.forEach(line=>add(line));else if(geometry?.type==='Polygon')geometry.coordinates.forEach(ring=>add(ring,true));else if(geometry?.type==='MultiPolygon')geometry.coordinates.forEach(polygon=>polygon.forEach(ring=>add(ring,true)));return sequences}
function uniqueVertexCount(sequence){return Math.max(0,sequence.coordinates.length-(sequence.closed&&coordinateEqual(sequence.coordinates[0],sequence.coordinates.at(-1))?1:0))}
function closeEditedSequence(sequence){if(!sequence.closed)return;const coordinates=sequence.coordinates;if(!coordinates.length)return;if(coordinates.length===1)coordinates.push(cloneJson(coordinates[0]));else coordinates[coordinates.length-1]=cloneJson(coordinates[0])}
function vertexHandleIcon(selected=false){return L.divIcon({className:`geometry-handle${selected?' selected':''}`,html:'<span></span>',iconSize:[20,20],iconAnchor:[10,10]})}
function midpointHandleIcon(){return L.divIcon({className:'geometry-midpoint',html:'<span></span>',iconSize:[14,14],iconAnchor:[7,7]})}
let generatedEdit=null,generatedGeometryHandles=[],selectedGeneratedVertex=null;
function clearGeneratedGeometryHandles(){generatedGeometryHandles.forEach(handle=>map.removeLayer(handle));generatedGeometryHandles=[];selectedGeneratedVertex=null;$('#removeVertex').classList.add('hidden')}
function renderGeneratedEditShape(){if(!generatedEdit)return;if(generatedEdit.shape)map.removeLayer(generatedEdit.shape);generatedEdit.shape=L.geoJSON(generatedEdit.feature,{pane:'fieldPane',interactive:false,style:{color:'#286fc0',weight:4,fillColor:'#286fc0',fillOpacity:.12,dashArray:'7 4',className:'generated-edit-shape'}}).addTo(map)}
function selectGeneratedVertex(sequence,index,marker){selectedGeneratedVertex={sequence,index};generatedGeometryHandles.filter(handle=>handle._omapVertex).forEach(handle=>handle.setIcon(vertexHandleIcon(handle===marker)));$('#removeVertex').classList.remove('hidden')}
function pushGeneratedUndo(){if(!generatedEdit)return;generatedEdit.undo.push(cloneJson(generatedEdit.feature.geometry));if(generatedEdit.undo.length>30)generatedEdit.undo.shift();$('#undoVertex').disabled=false}
function renderGeneratedGeometryHandles(){if(!generatedEdit)return;clearGeneratedGeometryHandles();if(generatedEdit.feature.geometry?.type==='Point'){const coordinates=generatedEdit.feature.geometry.coordinates,point=L.marker([coordinates[1],coordinates[0]],{pane:'fieldPane',icon:vertexHandleIcon(true),draggable:true,zIndexOffset:1200,title:'Flytta punktobjekt'}).addTo(map);point._omapVertex=true;point.on('dragstart',pushGeneratedUndo);point.on('drag',event=>{const latlng=event.target.getLatLng(),existing=generatedEdit.feature.geometry.coordinates;generatedEdit.feature.geometry.coordinates=[latlng.lng,latlng.lat,...existing.slice(2)];renderGeneratedEditShape()});generatedGeometryHandles.push(point);return}for(const sequence of editableSequences(generatedEdit.feature.geometry)){const count=uniqueVertexCount(sequence);for(let index=0;index<count;index++){const coordinate=sequence.coordinates[index],vertex=L.marker([coordinate[1],coordinate[0]],{pane:'fieldPane',icon:vertexHandleIcon(),draggable:true,zIndexOffset:1200,title:'Flytta eller välj hörn'}).addTo(map);vertex._omapVertex=true;vertex.on('dragstart',pushGeneratedUndo);vertex.on('drag',event=>{const point=event.target.getLatLng(),existing=sequence.coordinates[index];sequence.coordinates[index]=[point.lng,point.lat,...existing.slice(2)];closeEditedSequence(sequence);renderGeneratedEditShape()});vertex.on('dragend',()=>renderGeneratedGeometryHandles());vertex.on('click',event=>{L.DomEvent.stopPropagation(event);selectGeneratedVertex(sequence,index,vertex)});generatedGeometryHandles.push(vertex);if(!sequence.closed&&index===count-1)continue;const nextIndex=(index+1)%count,a=sequence.coordinates[index],b=sequence.coordinates[nextIndex],midpoint=L.marker([(a[1]+b[1])/2,(a[0]+b[0])/2],{pane:'fieldPane',icon:midpointHandleIcon(),zIndexOffset:1100,title:'Lägg till hörn'}).addTo(map);midpoint.on('click',event=>{L.DomEvent.stopPropagation(event);pushGeneratedUndo();const insertAt=index+1,newCoordinate=[(a[0]+b[0])/2,(a[1]+b[1])/2];sequence.coordinates.splice(insertAt,0,newCoordinate);closeEditedSequence(sequence);renderGeneratedEditShape();renderGeneratedGeometryHandles()});generatedGeometryHandles.push(midpoint)}}}
function closeGeneratedEditor({rerender=true}={}){if(!generatedEdit)return;const layerType=generatedEdit.layerType;if(generatedEdit.shape)map.removeLayer(generatedEdit.shape);clearGeneratedGeometryHandles();generatedEdit=null;document.body.classList.remove('generated-geometry-editing');$('#editBar').classList.add('hidden');$('#removeVertex').classList.add('hidden');$('#undoVertex').disabled=false;if(rerender)generatedLayerConfig(layerType)?.render()}
function startGeneratedGeometryEdit(layerType,feature){if(recording)return toast('Slutför eller avbryt pågående objekt först');if(feature.geometry?.type!=='Point'&&!editableSequences(feature.geometry).length)return toast('Den här geometritypen kan inte redigeras ännu');if(mode!=='manual')setMode('manual');clearSelection();map.closePopup();generatedEdit={layerType,feature,startGeometry:cloneJson(feature.geometry),sourceGeometry:cloneJson(feature.properties?.originalGeometry||feature.geometry),undo:[],shape:null};document.body.classList.add('generated-geometry-editing');$('#undoVertex').classList.remove('hidden');$('#undoVertex').disabled=true;$('#removeVertex').classList.add('hidden');$('#cancelEdit').classList.remove('hidden');$('#finishEdit').classList.remove('hidden');$('#finishEdit').textContent='Spara form';$('#deleteFeature').classList.add('hidden');$('#editBar').classList.remove('hidden');renderGeneratedEditShape();renderGeneratedGeometryHandles();toast(feature.geometry?.type==='Point'?'Dra den blå punkten till rätt position':'Dra blå hörn · tryck vita punkter för fler hörn')}
async function finishGeneratedGeometryEdit(){if(!generatedEdit)return;const {layerType,feature,sourceGeometry}=generatedEdit,p=feature.properties||(feature.properties={});if(!p.originalGeometry)p.originalGeometry=sourceGeometry;p[layerType==='global-objects'?'mapStatus':'status']='locally-edited';p.editedAt=new Date().toISOString();closeGeneratedEditor({rerender:false});await persistGeneratedLayer(layerType);toast('Formen sparades lokalt')}
