async function withdrawLocalObservation(obj){if(obj.syncStatus!=='submitted')return false;const response=await fetch('/api/submissions/withdraw',{method:'POST',headers:{'Content-Type':'application/json','X-OMapMaker-Device':deviceId},body:JSON.stringify({clientObservationIds:[obj.observationId]})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Observationen kunde inte återkallas');if(!result.withdrawn)throw new Error('Servern hittade ingen aktiv observation att återkalla');return true}
