async function applyLocalObjectAction(cat,obj,action){if(action==='edit'){if(mode!=='manual')setMode('manual');map.closePopup();selectFeature(cat,obj,layers.get(obj.id));return}if(!['exclude','delete','reset'].includes(action))return;try{if(action!=='reset')await withdrawLocalObservation(obj);ensureLocalOriginal(obj);if(action==='exclude'){obj.status='locally-excluded';obj.excludedAt=new Date().toISOString();markObjectChanged(obj)}else if(action==='delete'){obj.status='locally-deleted';obj.deletedAt=new Date().toISOString();markObjectChanged(obj)}else restoreLocalOriginal(obj);if(cat==='line')resnapCrossingsForBarrier(obj);clearSelection();map.closePopup();rerenderLocalObject(cat,obj);save();if(action!=='reset'&&obj.syncStatus==='local'){loadGlobalObjects().catch(()=>{});if(layerPrefs.evidence)loadEvidence().catch(()=>{})}toast({exclude:'Objektet uteslöts lokalt',delete:'Objektet raderades lokalt',reset:'Originalet återställdes'}[action])}catch(error){toast(error.message)}}
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-object-kind="local"]');if(!button||recording||generatedEdit)return;const entry=objectEntries().find(({obj})=>String(obj.id)===button.dataset.objectId);if(!entry)return;const action=button.dataset.objectAction;if(action==='delete'&&!confirm('Radera objektet från arbetsområdet? Det kan återställas senare.'))return;applyLocalObjectAction(entry.cat,entry.obj,action)});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-symbol-object-action]');if(!button||recording||generatedEdit)return;const entry=objectEntries().find(({obj})=>String(obj.id)===button.dataset.objectId),object=entry?.obj;if(!entry||localObjectIsInactive(object))return;const action=button.dataset.symbolObjectAction;ensureLocalOriginal(object);if(action==='crossing-break'&&entry.cat==='point'){object.breakBarrier=button.dataset.symbolSettingValue==='true';object.breakBarrierMode='manual';markObjectManuallyModified(object);save();map.closePopup();rerenderLocalObject('point',object);toast(object.breakBarrier?'Barriärlinjen bryts vid passagen':'Barriärlinjen behålls vid passagen');return}if(entry.cat!=='line')return;if(['cliff-side','fence-side','retaining-wall-side'].includes(action)){const property={"cliff-side":'downhillSide',"fence-side":'tagSide',"retaining-wall-side":'lowerSide'}[action];object[property]=button.dataset.symbolSettingValue;markObjectManuallyModified(object);save();map.closePopup();rerenderLocalObject('line',object);const subject={"cliff-side":'Branttaggar',"fence-side":'Staketstaggar',"retaining-wall-side":'Stödmurens lågsida'}[action];toast(`${subject}: ${object[property]==='right'?'höger':'vänster'} sida om ritningsriktningen`);return}if(action==='add-support'){if(mode!=='manual')setMode('manual');supportPlacement={objectId:object.id,largeMast:button.dataset.supportLarge==='true'};map.closePopup();toast('Tryck nära ledningen där stödet står');return}if(action==='delete-support'){object.supports=(object.supports||[]).filter(support=>String(support.id)!==button.dataset.supportId);markObjectManuallyModified(object);save();map.closePopup();rerenderLocalObject('line',object);toast('Stödet togs bort')}});
function refreshSymbolPresentation(){state.observations.forEach(o=>layers.get(o.id)?.setIcon(pointIcon(o)));state.tracks.forEach(o=>{const layer=layers.get(o.id),symbol=manualObjectSymbol('line',o);if((isCliffSymbol(symbol)||isDecoratedLineSymbol(symbol)||isPowerLineSymbol(symbol))&&selected?.obj!==o){rerenderLocalObject('line',o);return}if(layer?._omapComposite){layer._omapComposite.outer.setStyle(isomLineStyle(symbol,o));layer._omapComposite.inner.setStyle(isomCompositeInnerStyle(symbol,o))}else layer?.setStyle?.(isomLineStyle(symbol,o))});state.areas.forEach(o=>{const symbol=manualObjectSymbol('area',o),properties={...o,boundary:o.objectType==='forbidden'?'clear':o.boundary};layers.get(o.id)?.setStyle(isomAreaStyle(symbol,properties))});renderLandCover();renderProjectContours();renderBuildings();renderPavedAreas();renderRoads();renderInfrastructure();renderGlobalObjects()}
map.on('zoomend',()=>{if(workspace?.symbolDisplayMode==='print')refreshSymbolPresentation();else{renderRoads();renderInfrastructure()}renderMagneticNorthLines()});

function labels(){
  const pointButton=$('#pointAction'), pointActive=recording?.cat==='point';
  $('#pointLabel').textContent=name('point',pointActive?recording.type:prefs.point);
  pointButton.classList.toggle('active-tool',pointActive);
  pointButton.querySelector('span').textContent=pointActive?'PLACERA PÅ KARTAN':'PLACERA';
  for(const cat of ['line','area']){
    const button=$(`#${cat}Action`), active=recording?.cat===cat, noun=name(cat,active?recording.type:prefs[cat]);
    button.classList.toggle('recording',active);
    button.querySelector('span').textContent=active?(recording.mode==='gps'?'MÄTER':'RITAR'):(mode==='gps'?'SPELA IN':'RITA');
    button.querySelector('b').textContent=active?`■ ${noun}`:noun;
  }
}
function setMode(next){
  if(recording?.mode==='gps'&&next!=='gps')return toast('Avsluta eller avbryt GPS-inspelningen först');
  if(recording){cancelDrawing(false)}
  clearSelection();supportPlacement=null;mode=next;localStorage.setItem('omapmaker.mode',mode);
  document.body.classList.toggle('manual-mode',mode==='manual');document.body.classList.toggle('gps-mode',mode==='gps');
  $('#gpsMode').classList.toggle('active',mode==='gps');$('#manualMode').classList.toggle('active',mode==='manual');
  $('#modeHint').textContent=mode==='gps'?'GPS · Telefonens position':'MANUELLT · Rita på kartan';
  state.observations.forEach(o=>{const m=layers.get(o.id);mode==='manual'&&!localObjectIsInactive(o)?m.dragging.enable():m.dragging.disable()});labels();
}
$('#gpsMode').onclick=()=>setMode('gps');$('#manualMode').onclick=()=>setMode('manual');

function identity(){const id=crypto.randomUUID();return{id,observationId:id,syncStatus:'local',version:1}}
function addPoint(ll,accuracy,source){if(source==='gps'&&accuracy>50)return toast(`GPS ±${Math.round(accuracy)} m · för osäkert`);const o={...identity(),objectType:prefs.point,symbol:item('point',prefs.point)[1],coordinates:[ll.lng,ll.lat],accuracy,source,quality:'unverified',createdAt:new Date().toISOString()};applyDefaultSymbolSettings(o,o.symbol);if(String(o.symbol)==='519')snapCrossingPoint(o);ensureLocalOriginal(o);state.observations.push(o);renderPoint(o);save();toast(`${name('point',prefs.point)} sparad`)}
function showDrawingBar(){clearSelection();$('#undoVertex').classList.remove('hidden');$('#cancelEdit').classList.remove('hidden');$('#finishEdit').classList.remove('hidden');$('#finishEdit').textContent='Slutför';$('#deleteFeature').classList.add('hidden');$('#editBar').classList.remove('hidden')}
function updateTemp(){if(tempLayer)map.removeLayer(tempLayer);if(!currentCoords.length)return;tempLayer=recording.cat==='area'?L.polygon(latlngs(currentCoords),{...areaStyle(recording.type),className:'temp-shape'}).addTo(map):L.polyline(latlngs(currentCoords),{...lineStyle(recording.type),className:'temp-shape'}).addTo(map)}
function beginShape(cat){recording={mode,cat,type:prefs[cat]};currentCoords=[];showDrawingBar();labels();toast(mode==='gps'?`${name(cat,prefs[cat])} spelas in`:`Tryck ut ${cat==='line'?'linjen':'områdets hörn'}`)}
function finishDrawing(){if(!recording)return;const min=recording.cat==='area'?3:2;if(currentCoords.length<min)return toast(`Minst ${min} punkter behövs`);const obj={...identity(),objectType:recording.type,symbol:item(recording.cat,recording.type)[1],coordinates:[...currentCoords],source:recording.mode,quality:'unverified',createdAt:new Date().toISOString()};applyDefaultSymbolSettings(obj,obj.symbol);ensureLocalOriginal(obj);if(recording.cat==='line'){state.tracks.push(obj);renderLine(obj)}else{state.areas.push(obj);renderArea(obj)}cancelDrawing(false);save();toast('Objekt sparat')}
function cancelDrawing(message=true){if(tempLayer)map.removeLayer(tempLayer);tempLayer=null;recording=null;currentCoords=[];$('#editBar').classList.add('hidden');labels();if(message)toast('Ritningen avbröts')}
function action(cat){
  if(cat==='point'){if(mode==='manual'){recording={mode:'manual',cat:'point',type:prefs.point};labels();toast(`${name('point',prefs.point)} vald · tryck på kartan`)}else if(lastPosition)addPoint(lastPosition.latlng,lastPosition.accuracy,'gps');else toast('GPS söker position · försök igen strax');return}
  if(recording?.cat===cat)return finishDrawing();
  if(recording)return toast('Slutför eller avbryt pågående objekt först');
  if(mode==='gps'&&!lastPosition)return toast('GPS söker position · försök igen strax');
  if(mode==='gps'&&lastPosition.accuracy>50)return toast('GPS-kvaliteten är för låg');
  beginShape(cat);
}
$('#pointAction').onclick=()=>action('point');$('#lineAction').onclick=()=>action('line');$('#areaAction').onclick=()=>action('area');
map.on('click',e=>{if(mode!=='manual')return;if(supportPlacement){const object=state.tracks.find(item=>item.id===supportPlacement.objectId),snapped=object&&nearestPointOnLine(object.coordinates,[e.latlng.lng,e.latlng.lat]);if(!object||!snapped){supportPlacement=null;return toast('Stödet kunde inte placeras')}object.supports=Array.isArray(object.supports)?object.supports:[];object.supports.push({id:crypto.randomUUID(),coordinates:snapped.coordinate,angleDegrees:snapped.angleDegrees,supportType:String(object.symbol)==='511'?'tower':'pole',largeMast:Boolean(supportPlacement.largeMast)});supportPlacement=null;markObjectManuallyModified(object);save();rerenderLocalObject('line',object);toast('Stödet placerades exakt på ledningslinjen');return}if(recording?.cat==='point'){addPoint(e.latlng,0,'manual');recording=null;labels()}else if(recording?.mode==='manual'){currentCoords.push([e.latlng.lng,e.latlng.lat,0,Date.now(),null,null]);updateTemp()}});
$('#undoVertex').onclick=()=>generatedEdit?undoGeneratedGeometryEdit():(currentCoords.pop(),updateTemp());$('#removeVertex').onclick=removeSelectedGeneratedVertex;$('#cancelEdit').onclick=()=>generatedEdit?cancelGeneratedGeometryEdit():cancelDrawing();$('#finishEdit').onclick=()=>generatedEdit?finishGeneratedGeometryEdit():selected?clearSelection():finishDrawing();
$('#deleteFeature').onclick=()=>{if(!selected)return;const {cat,obj}=selected;if(!confirm('Radera objektet från arbetsområdet? Det kan återställas senare.'))return;applyLocalObjectAction(cat,obj,'delete')};

function openSheet(cat){if(recording)return toast('Slutför eller avbryt pågående objekt först');$('#sheetCategory').textContent=cat==='point'?'PLACERA':cat==='line'?'LINJE':'OMRÅDE';$('#sheetTitle').textContent=`Välj ${cat==='point'?'punktobjekt':cat==='line'?'linjeobjekt':'områdestyp'}`;$('#sheetOptions').innerHTML='';catalog[cat].forEach(d=>{const b=document.createElement('button');b.type='button';b.className=d[0]===prefs[cat]?'selected':'';b.innerHTML=`<span class="symbol">${cat==='point'?pointSvg(d[0]):d[1]}</span><span>${d[2]}<small style="display:block;color:#748078">${isomClaim(d[1],manualTypes[d[0]].geometry)}</small></span>`;b.onclick=()=>{prefs[cat]=d[0];save();labels();$('#objectSheet').close();toast(`${d[2]} vald`)};$('#sheetOptions').append(b)});$('#objectSheet').showModal()}
document.querySelectorAll('.tool-menu').forEach(b=>b.onclick=()=>openSheet(b.dataset.category));

function quality(a){return a<=3?['excellent',`★ GPS ± ${Math.round(a)} m · Utmärkt`]:a<=10?['good',`GPS ± ${Math.round(a)} m · Bra`]:a<=50?['warn',`GPS ± ${Math.round(a)} m · Osäkert`]:['bad',`GPS ± ${Math.round(a)} m · Otillräckligt`]}
function refreshGpsButton(){const running=watchId!==null,button=$('#gpsQuality');button.setAttribute('aria-pressed',String(running));button.title=running?'Stäng av GPS':'Starta GPS';if(!running)button.querySelector('span').textContent='GPS av · Starta'}
function oneShotPosition(button,onSuccess){if(!navigator.geolocation)return toast('Positionering stöds inte av webbläsaren');if(button){button.disabled=true;button.classList.add('busy');button.setAttribute('aria-busy','true')}navigator.geolocation.getCurrentPosition(position=>{const latlng=L.latLng(position.coords.latitude,position.coords.longitude);lastPosition={latlng,accuracy:position.coords.accuracy};onSuccess(latlng,position.coords.accuracy);if(button){button.disabled=false;button.classList.remove('busy');button.removeAttribute('aria-busy')}},error=>{if(button){button.disabled=false;button.classList.remove('busy');button.removeAttribute('aria-busy')}toast(error.code===1?'Positionering saknar tillstånd':'Positionen kunde inte hämtas')},{enableHighAccuracy:true,maximumAge:5000,timeout:15000})}
function centerOnCurrentPosition(){const button=$('#centerLocationButton'),show=latlng=>map.setView(latlng,Math.max(map.getZoom(),17),{animate:true});if(lastPosition)return show(lastPosition.latlng);oneShotPosition(button,show)}
