function exportRenderOptions(settings){const paper=paperDimensions(settings),center=settings.exportExtent==='view'?map.getCenter():(settings.printCenter||selectedPrintCenter||workspace?.center);return{scale:Number(workspace?.scale)||10000,declination:workspace?.magneticDeclination,center,widthMm:paper.widthMm,heightMm:paper.heightMm}}
function renderExportPreflight(settings=writeExportSettings()){const box=$('#exportPreflight'),list=$('#exportPreflightIssues');if(!workspace){latestPreflight=null;box.className='preflight-result failed';box.querySelector('b').textContent='Arbetsområde krävs';box.querySelector('span').textContent='Skala och magnetisk nord saknas.';list.replaceChildren();$('#preparePrint').disabled=true;return null}latestPreflight=normRenderer.preflight(currentMapFeatures(),exportRenderOptions(settings));box.className=`preflight-result ${latestPreflight.errors?'failed':latestPreflight.warnings?'warning':'passed'}`;box.querySelector('b').textContent=latestPreflight.errors?`${latestPreflight.errors} blockerande fel · ${latestPreflight.warnings} kartografiska varningar`:latestPreflight.warnings?`Inga blockerande fel · ${latestPreflight.warnings} kartografiska varningar`:'Godkänd';box.querySelector('span').textContent=`${latestPreflight.featureCount} synliga kartobjekt · ISOM-register v${latestPreflight.registryVersion}`;list.replaceChildren();const groups=new Map;for(const issue of latestPreflight.issues){if(!groups.has(issue.code))groups.set(issue.code,[]);groups.get(issue.code).push(issue)}for(const issues of groups.values()){const first=issues[0],item=document.createElement('li');item.className=first.severity;item.textContent=issues.length===1?first.message:`${issues.length} kontrollpunkter: ${first.message}`;list.append(item)}$('#exportPreflightDetails').open=latestPreflight.errors>0;$('#preparePrint').disabled=latestPreflight.errors>0;return latestPreflight}
function openExportSheet(){const settings=readExportSettings();selectedPrintCenter=settings.printCenter&&Number.isFinite(Number(settings.printCenter.lat))?{lat:Number(settings.printCenter.lat),lng:Number(settings.printCenter.lng)}:(workspace?.center||null);exportSettingIds.forEach(id=>{const element=$(`#${id}`),value=settings[id];if(element.type==='checkbox')element.checked=Boolean(value);else element.value=value??''});$('#exportScaleValue').textContent=workspace?`1:${Number(workspace.scale).toLocaleString('sv-SE')}`:'Saknas';$('#exportContourValue').textContent=workspace?`${String(workspace.contourInterval).replace('.',',')} m`:'Saknas';$('#preparePrint').disabled=!workspace;const note=$('#exportComplianceNote');note.querySelector('b').textContent=workspace?'Normstyrd vektorförhandsversion':'Arbetsområde krävs';note.querySelector('span').textContent=workspace?'Kartan roteras till magnetisk nord. Symboler, 601-linjer, IOF-färgernas RGB-förhandsvisning och lagerordning hämtas från samma register. Slutlig skrivarkalibrering krävs fortfarande.':'PDF-export kräver ett arbetsområde med skala, ekvidistans och deklination.';syncOptionalExportFields();updateExportAreaSummary();renderExportPreflight(settings);$('#exportSheet').showModal()}
function updatePrintAreaLayer(){if(!workspace)return;selectedPrintCenter={lat:map.getCenter().lat,lng:map.getCenter().lng};const settings=printableSettingsFromForm(),bounds=printBounds(selectedPrintCenter,settings),dimensions=printGroundDimensions(settings),inside=workspaceBounds?.contains(bounds);if(printAreaLayer)printAreaLayer.setBounds(bounds);else printAreaLayer=L.rectangle(bounds,{pane:'fieldPane',color:'#c3258d',weight:3,dashArray:'9 6',fillColor:'#fff',fillOpacity:.05,interactive:false,className:'print-area-boundary'}).addTo(map);$('#printAreaPickerSummary').textContent=`${(dimensions.widthMetres/1000).toFixed(2).replace('.',',')} × ${(dimensions.heightMetres/1000).toFixed(2).replace('.',',')} km · ${inside?'inom arbetsområdet':'delvis utanför arbetsområdet'}`}
function startPrintAreaSelection(){if(!workspace)return;writeExportSettings();printAreaOriginalCenter=selectedPrintCenter?{...selectedPrintCenter}:null;$('#exportSheet').close();document.body.classList.add('print-area-mode');$('#printAreaPicker').hidden=false;const settings=printableSettingsFromForm(),center=selectedPrintCenter||workspace.center,bounds=printBounds(center,settings);map.fitBounds(bounds,{paddingTopLeft:[35,105],paddingBottomRight:[35,35],animate:false});printAreaMoveHandler=updatePrintAreaLayer;map.on('move',printAreaMoveHandler);updatePrintAreaLayer()}
function stopPrintAreaSelection(confirm){if(printAreaMoveHandler)map.off('move',printAreaMoveHandler);printAreaMoveHandler=null;if(!confirm)selectedPrintCenter=printAreaOriginalCenter;if(printAreaLayer)map.removeLayer(printAreaLayer);printAreaLayer=null;$('#printAreaPicker').hidden=true;document.body.classList.remove('print-area-mode');if(confirm)writeExportSettings();openExportSheet()}
function addPrintMetadata(label,value){if(!value)return;const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;row.append(dt,dd);$('#printMetadata').append(row)}
function buildPrintInformation(settings){const scale=`1:${Number(workspace.scale).toLocaleString('sv-SE')}`,interval=`${String(workspace.contourInterval).replace('.',',')} m`,title=settings.includeMapName?settings.exportMapName.trim():'',declination=workspace.magneticDeclination;$('#printMapTitle').textContent=title;$('#printMapTitle').hidden=!title;$('#printMetadata').replaceChildren();addPrintMetadata('Skala',scale);addPrintMetadata('Ekvidistans',interval);addPrintMetadata('Magnetisk nord',declination===null||declination===''?'Ej angiven':`${Number(declination)>=0?'+':''}${Number(declination).toFixed(1).replace('.',',')}° mot kartnorr`);if(workspace.magneticNorthCalculation)addPrintMetadata('Magnetisk modell',`${workspace.magneticNorthCalculation.model} · ${workspace.magneticNorthCalculation.date}`);if(settings.includeIssuer)addPrintMetadata('Kartutgivare',settings.exportIssuer.trim());if(settings.includeSurveyYear)addPrintMetadata('Karteringsår',settings.exportSurveyYear);if(settings.includeSpecification)addPrintMetadata('Kartnorm',settings.exportSpecification.trim());if(settings.includeMappers)addPrintMetadata('Kartritare',settings.exportMappers.trim());if(settings.includePrintShop)addPrintMetadata('Tryckeri',settings.exportPrintShop.trim());if(settings.includeCopyright)addPrintMetadata('Copyright',settings.exportCopyright.trim())}
function calibratedPrintZoom(scale,latitude){const metresPerCssPixel=Number(scale)*.0254/96,metresPerPixelAtZoomZero=156543.03392804097*Math.cos(Number(latitude)*Math.PI/180);return Math.log2(metresPerPixelAtZoomZero/metresPerCssPixel)}
let printRestore=null;
function finishPrinting(){if(!printRestore)return;document.body.classList.remove('print-layout-active');document.body.style.removeProperty('--print-width');document.body.style.removeProperty('--print-height');document.querySelector('#printPageStyle')?.remove();$('#vectorPrintMap').replaceChildren();printRestore=null;setTimeout(()=>map.invalidateSize(),0)}
function preparePrinting(settings){if(!workspace)return toast('Skapa eller öppna ett arbetsområde först');const paper=paperDimensions(settings),options=exportRenderOptions(settings),check=renderExportPreflight(settings);buildPrintInformation(settings);$('#printPrototypeMark').textContent=check.errors?`OMAPMAKER PROTOTYP · NORMKONTROLL: ${check.errors} FEL`:'OMAPMAKER PROTOTYP · EJ KARTKONTROLLERAD';document.querySelector('#printPageStyle')?.remove();const pageStyle=document.createElement('style');pageStyle.id='printPageStyle';pageStyle.textContent=`@page{size:${paper.paperWidth}mm ${paper.paperHeight}mm;margin:${paper.margin}mm}`;document.head.append(pageStyle);$('#vectorPrintMap').innerHTML=normRenderer.buildVectorSvg(currentMapFeatures(),options);document.body.style.setProperty('--print-width',`${paper.widthMm}mm`);document.body.style.setProperty('--print-height',`${paper.heightMm}mm`);document.body.classList.add('print-layout-active');printRestore={};window.addEventListener('afterprint',finishPrinting,{once:true});window.addEventListener('focus',()=>setTimeout(finishPrinting,400),{once:true});$('#exportSheet').close();requestAnimationFrame(()=>setTimeout(()=>{try{window.print()}finally{setTimeout(finishPrinting,500)}},250))}
$('#export').onclick=openExportSheet;$('#closeExportSheet').onclick=()=>$('#exportSheet').close();$('#exportGeojson').onclick=exportGeojson;$('#choosePrintArea').onclick=startPrintAreaSelection;$('#cancelPrintArea').onclick=()=>stopPrintAreaSelection(false);$('#confirmPrintArea').onclick=()=>stopPrintAreaSelection(true);$('#centerPrintOnWorkspace').onclick=()=>map.setView(workspace.center,map.getZoom(),{animate:true});document.querySelectorAll('#exportSheet .optional-information input[type=checkbox]').forEach(input=>input.onchange=syncOptionalExportFields);for(const id of ['exportPaper','exportOrientation','exportMargin','exportExtent'])$(`#${id}`).onchange=()=>{updateExportAreaSummary();renderExportPreflight()};$('#exportForm').onsubmit=event=>{event.preventDefault();const settings=writeExportSettings();preparePrinting(settings)};
let activeContourJobId=null;
function setContourControlsRunning(running){
  $('#runContourGeneration').disabled=running;$('#runContourGeneration').textContent=running?'Arbetar…':'Generera höjdkurvor';$('#cancelContourGeneration').hidden=!running;$('#cancelContourGeneration').disabled=false;$('#cancelContourGeneration').textContent='Avbryt';
}
const toolbar=$('#toolbar'),collapseToolbar=$('#collapseToolbar'),toolbarPreferenceKey='omapmaker.toolbarCollapsed.v2';function setToolbarCollapsed(collapsed,persist=true){toolbar.classList.toggle('collapsed',collapsed);collapseToolbar.setAttribute('aria-expanded',String(!collapsed));collapseToolbar.textContent=collapsed?'Ritverktyg':'Dölj';collapseToolbar.setAttribute('aria-label',collapsed?'Visa ritverktyg':'Dölj ritverktyg');if(persist)localStorage.setItem(toolbarPreferenceKey,String(collapsed))}const savedToolbarPreference=localStorage.getItem(toolbarPreferenceKey);setToolbarCollapsed(savedToolbarPreference===null?matchMedia('(max-width: 520px)').matches:savedToolbarPreference==='true',false);collapseToolbar.onclick=()=>{if(recording||selected||generatedEdit)return toast('Slutför eller avbryt pågående objekt först');setToolbarCollapsed(!toolbar.classList.contains('collapsed'))};
function refreshContourSettingsSummary(){const interval=Number(workspace?.contourInterval||5);const summary=$('#contourSettingsSummary');summary.querySelector('div:first-child b').textContent=`${String(interval).replace('.',',')} meter`}
function renderContourJob(job){
  const panel=$('#contourProgressPanel'),progress=$('#contourProgress'),value=$('#contourProgressValue'),transfer=$('#contourTransferText');panel.hidden=false;
  const stageLabels={'queued':'Väntar','checking-cache':'Kontrollerar cache','height-cache':'Höjddata i cache','authenticating':'Ansluter','searching':'Söker höjddata','downloading':'Hämtar höjddata','preparing':'Förbereder höjddata','contour-cache':'Kurvor i cache','generating':'Skapar höjdkurvor','cancelling':'Avbryter','complete':'Klart','cancelled':'Avbrutet'};
  $('#contourStageText').textContent=stageLabels[job.stage]||'Arbetar';$('#contourStatus').textContent=job.message||'Höjdjobbet arbetar…';
  const percent=Number(job.progressPercent);if(!job.progressIndeterminate&&Number.isFinite(percent)){progress.value=Math.max(0,Math.min(100,percent));value.textContent=`${Math.round(percent)} %`}else{progress.removeAttribute('value');value.textContent=''}
  const loaded=formatBytes(job.loadedBytes),total=formatBytes(job.totalBytes),fileCount=Number(job.fileCount||0),fileIndex=Number(job.fileIndex||0);transfer.textContent=loaded?(total?`${loaded} av ${total}${fileCount>1?` · ruta ${fileIndex}/${fileCount}`:''}`:`${loaded} hämtat${fileCount>1?` · ruta ${fileIndex}/${fileCount}`:''}`):'';
  if(job.heightDataCached===true){$('#contourCacheInfo').className='contour-cache-info cached';$('#contourCacheInfo').textContent='Höjddata för arbetsområdet återanvänds från serverns cache.'}
  else if(job.heightDataCached===false){$('#contourCacheInfo').className='contour-cache-info download';$('#contourCacheInfo').textContent='Ny höjddata hämtas och sparas på servern för framtida användning.'}
}
async function refreshContourCacheInfo(){
  const info=$('#contourCacheInfo'),bbox=workspaceBbox();if(!bbox)return;info.className='contour-cache-info';info.textContent='Kontrollerar serverns cache…';
  try{const data=await jsonResponse(await fetch('/api/height-coverage',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bbox})}));if(data.cached){info.className='contour-cache-info cached';info.textContent=`Höjddata finns redan på servern${data.sourceFiles?` · ${data.sourceFiles} ${data.sourceFiles===1?'fil':'filer'}`:''}.`}else{info.className='contour-cache-info download';info.textContent='Höjddata saknas för delar av området och hämtas vid generering.'}}
  catch(error){info.className='contour-cache-info';info.textContent=`Cache kunde inte kontrolleras: ${error.message}`}
}
$('#generateContoursButton').onclick=()=>{$('#layersSheet').close();refreshContourSettingsSummary();if(!activeContourJobId){$('#contourStatus').textContent='';$('#contourProgressPanel').hidden=true;refreshContourCacheInfo()}$('#contourSheet').showModal()};
async function runContourJob(payload,status){
  status.textContent='Söker efter färdiga höjdkurvor på servern…';
  const central=await resolveCentralLayer('contours');
  if(central){status.textContent='Återanvänder centrala höjdkurvor…';return central.layer}
  status.textContent='Startar höjdjobb på servern…';
  const created=await jsonResponse(await fetch('/api/contour-jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}));
  if(!created.id)throw new Error('Servern returnerade inget jobbnummer');activeContourJobId=created.id;renderContourJob(created);
  for(let attempt=0;attempt<900;attempt++){
    await wait(attempt<5?700:1200);
    const job=await jsonResponse(await fetch(`/api/contour-jobs/${encodeURIComponent(created.id)}`,{cache:'no-store'}));
    renderContourJob(job);
    if(job.status==='complete'){if(!job.result)throw new Error('Höjdkurvorna skapades men resultatet kunde inte hämtas. Försök igen; serverns cache gör nästa körning snabb.');return job.result}
    if(job.status==='cancelled'){const error=new Error(job.message||'Genereringen avbröts.');error.cancelled=true;throw error}
    if(job.status==='error')throw new Error(job.message||'Höjdjobbet misslyckades');
  }
  throw new Error('Höjdjobbet tog för lång tid. Det kan fortsätta på servern; försök igen om en stund.');
}
$('#cancelContourGeneration').onclick=async()=>{if(!activeContourJobId)return;const button=$('#cancelContourGeneration');button.disabled=true;button.textContent='Avbryter…';try{const job=await jsonResponse(await fetch(`/api/contour-jobs/${encodeURIComponent(activeContourJobId)}`,{method:'DELETE'}));renderContourJob(job)}catch(error){button.disabled=false;button.textContent='Avbryt';$('#contourStatus').textContent=`Kunde inte avbryta: ${error.message}`}};
$('#runContourGeneration').onclick=async()=>{
  const bbox=workspaceBbox();if(!bbox)return toast('Skapa eller öppna ett arbetsområde först');
  const button=$('#runContourGeneration'),status=$('#contourStatus');
  const payload={bbox,interval:Number(workspace?.contourInterval||5),generalization:'detailed'};
  setContourControlsRunning(true);$('#contourProgressPanel').hidden=false;
  try{
    const data=await runContourJob(payload,status);
    if(data.type!=='FeatureCollection')throw new Error('Ogiltigt svar från höjdtjänsten');
    projectContourData=data;await storeContourData(data);layerPrefs.projectContours=true;$('#projectContoursVisible').checked=true;saveLayerPrefs();renderProjectContours();refreshContourMeta();
    status.textContent=`Klart: ${data.features.length} kurvlinjer`;toast('Höjdkurvor genererade');setTimeout(()=>$('#contourSheet').close(),700);
  }catch(error){status.textContent=location.hostname.includes('github.io')?'Höjdtjänsten är ännu inte driftsatt. Starta den lokala prototypen för att generera kurvor.':error.message;if(error.cancelled)toast('Genereringen avbröts')}
  finally{activeContourJobId=null;setContourControlsRunning(false);refreshContourCacheInfo()}
};
